function Convert-ProjectPathToGalleryUrl([string]$ProjectPath) {
    return ('../../' + $ProjectPath.Replace('\\','/'))
}
function Encode([string]$Text) { return [System.Net.WebUtility]::HtmlEncode($Text) }
function New-AssetLink([string]$ProjectPath, [string]$Label, [bool]$Image) {
    if ([string]::IsNullOrWhiteSpace($ProjectPath)) { return '<div class="missing"><strong>후보 PNG 없음</strong><span>전용 원화가 없어 Window 상태 캡처로 확인합니다.</span></div>' }
    $url = Convert-ProjectPathToGalleryUrl $ProjectPath
    $exists = Test-Path -LiteralPath (Join-Path $ProjectRoot $ProjectPath) -PathType Leaf
    if (-not $exists) { return ('<div class="missing"><strong>누락 파일</strong><code>' + (Encode $ProjectPath) + '</code></div>') }
    if ($Image) { return ('<figure class="art-view"><a href="' + $url + '" target="_blank" rel="noopener" title="원본 PNG 열기"><img src="' + $url + '" alt="' + (Encode $Label) + ' 우향 후보"></a><figcaption>' + (Encode $Label) + ' · 우향</figcaption></figure>') }
    return ('<a class="file-link" href="' + $url + '" target="_blank" rel="noopener">' + (Encode $Label) + '</a>')
}

$cards = foreach ($r in $records) {
    $art = New-AssetLink $r.Art ($r.Title + ' 원본') $true
    $safe = if ($r.Safe) { New-AssetLink $r.Safe ($r.Title + ' safe 파생본') $true } else { '' }
    $images = if ($r.Art) {
        '<div class="view-pair"><div class="facing"><div class="facing-label">우향 · 192px</div>' + $art + '</div><div class="facing"><div class="facing-label">좌향 · 192px 미러</div>' + $(if ($r.Art -and (Test-Path -LiteralPath (Join-Path $ProjectRoot $r.Art) -PathType Leaf)) { '<figure class="art-view mirrored"><a href="' + (Convert-ProjectPathToGalleryUrl $r.Art) + '" target="_blank" rel="noopener" title="원본 PNG 열기"><img src="' + (Convert-ProjectPathToGalleryUrl $r.Art) + '" alt="' + (Encode $r.Title) + ' 좌향 미러"></a><figcaption>좌향 비교용 반전</figcaption></figure>' } else { $art }) + '</div></div>'
    } else { '<div class="missing large"><strong>전용 turn 후보 PNG 없음</strong><span>절차적 turn 상태는 아래 Window 캡처와 근거 문서에서 확인하세요.</span></div>' }
    $safePanel = if ($safe) { '<details class="safe-detail"><summary>safe 파생본 보기</summary><div class="view-pair">' + $safe + '<figure class="art-view mirrored"><a href="' + (Convert-ProjectPathToGalleryUrl $r.Safe) + '" target="_blank" rel="noopener" title="safe 원본 PNG 열기"><img src="' + (Convert-ProjectPathToGalleryUrl $r.Safe) + '" alt="' + (Encode $r.Title) + ' safe 좌향"><figcaption>safe · 좌향 비교용 반전</figcaption></a></figure></div></details>' } else { '' }
    $evidence = foreach ($p in $r.Evidence) { New-AssetLink $p ([System.IO.Path]::GetFileName($p)) $false }
    $docs = foreach ($p in $r.Docs) { New-AssetLink $p ([System.IO.Path]::GetFileName($p)) $false }
    $badgeClass = if ($r.Approval -eq 'approved') { 'approved' } elseif ($r.Approval -eq 'procedural') { 'procedural' } else { 'pending' }
    $meta = '<span class="badge ' + $badgeClass + '">' + (Encode $r.Status) + '</span><span class="tag">' + (Encode $r.Group) + '</span>'
    $criteria = '<dl class="checks"><div><dt>Identity</dt><dd>' + (Encode $r.Identity) + '</dd></div><div><dt>접지 · anchor</dt><dd>' + (Encode $r.Ground) + '</dd></div><div><dt>프레임 팝</dt><dd>' + (Encode $r.Pop) + '</dd></div></dl>'
    '<article class="card" id="' + $r.Id + '" data-status="' + $r.Approval + '" data-tags="' + (Encode $r.Tags) + '"><header class="card-head"><div><div class="eyebrow">' + (Encode $r.Group) + '</div><h3>' + (Encode $r.Title) + '</h3><p>' + (Encode $r.Note) + '</p></div><div class="badges">' + $meta + '</div></header>' + $images + $safePanel + $criteria + '<div class="links"><section><h4>Window · 비교 캡처</h4><div class="link-list">' + ($evidence -join '') + '</div></section><section><h4>근거 문서</h4><div class="link-list">' + ($docs -join '') + '</div></section></div><label class="review-note">사람 검토 메모 <textarea rows="2" placeholder="개인 검토 중 임시 메모 (이 페이지는 저장하지 않음)"></textarea></label></article>'
}

