to-fit,minmax(min(100%,640px),1fr));gap:18px}.card{background:linear-gradient(145deg,#17222c,#111820);border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 16px 38px #0003;scroll-margin-top:80px}.card-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.card-head h3{font-size:1.28rem;margin:3px 0}.card-head p{color:var(--muted);font-size:.87rem;margin:3px 0}.badges{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.badge,.tag{border-radius:999px;padding:5px 9px;font-size:.77rem;font-weight:750;white-space:nowrap}.badge.approved{color:#071b15;background:var(--mint)}.badge.pending{color:#261b08;background:var(--amber)}.badge.procedural{color:#d5e5ef;background:#425466}.tag{border:1px solid var(--line);color:var(--muted)}.view-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:15px 0}.facing{min-width:0}.facing-label{color:var(--muted);font-size:.78rem;margin:0 0 5px}.art-view{margin:0;background-color:#101820;background-image:linear-gradient(45deg,#23303a 25%,transparent 25%),linear-gradient(-45deg,#23303a 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#23303a 75%),linear-gradient(-45deg,transparent 75%,#23303a 75%);background-size:20px 20px;background-position:0 0,0 10px,10px -10px,-10px 0;border:1px solid #334553;border-radius:12px;overflow:hidden;text-align:center}.art-view img{display:block;width:192px;height:192px;object-fit:contain;image-rendering:pixelated;margin:0 auto}.art-view.mirrored img{transform:scaleX(-1)}.art-view figcaption{font-size:.72rem;color:var(--muted);background:#111923d9;padding:4px}.safe-detail{margin:8px 0}.safe-detail summary{cursor:pointer;color:#9bdcff}.safe-detail .art-view img{width:192px;height:192px}body.zoom3 .art-view img{width:576px;height:576px;max-width:none}body.zoom3 .facing{overflow:auto}.missing{border:1px dashed #a57548;border-radius:10px;padding:12px;color:#ffdca8;display:flex;flex-direction:column;gap:5px;min-height:96px;justify-content:center}.missing code{font-size:.72rem;overflow-wrap:anywhere}.missing.large{margin:15px 0;min-height:145px;text-align:center}.checks{margin:15px 0;display:grid;gap:8px}.checks div{display:grid;grid-template-columns:110px 1fr;gap:10px;border-top:1px solid #263541;padding-top:8px}.checks dt{font-size:.8rem;font-weight:800;color:var(--mint)}.checks dd{margin:0;color:#d1dde3;font-size:.9rem}.links{display:grid;grid-template-columns:1fr 1fr;gap:10px;border-top:1px solid var(--line);padding-top:12px}.links h4{font-size:.8rem;color:var(--muted);margin:0 0 7px}.link-list{display:flex;flex-wrap:wrap;gap:6px}.review-note{display:block;margin-top:14px;color:var(--muted);font-size:.8rem}.review-note textarea{display:block;width:100%;margin-top:5px;border:1px solid var(--line);border-radius:8px;background:#10171e;color:var(--text);padding:8px;font:inherit}footer{padding:22px 0 50px;color:var(--muted);border-top:1px solid var(--line)}.template{display:inline-block;background:var(--mint);color:#081a15;font-weight:850;padding:10px 14px;border-radius:9px;text-decoration:none}@media(max-width:650px){.card-head{display:block}.badges{justify-content:flex-start;margin-top:10px}.links{grid-template-columns:1fr}.checks div{grid-template-columns:95px 1fr}.art-view img{width:min(192px,100%);height:auto;aspect-ratio:1}}
